import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || './data/workboard.sqlite';
if (databasePath !== ':memory:') mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
)`);
const listTasks = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? ORDER BY id ASC');
const findTask = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
function taskData(task) { return { ...task, completed: Boolean(task.completed) }; }
async function readBody(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) throw Object.assign(new Error('Request too large'), { status: 413 });
  }
  try { return JSON.parse(body); }
  catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id ASC');
const findProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);
function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(body));
}
const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') return json(res, 200, { status: 'ok' });
    if (req.method === 'GET' && path === '/api/projects') return json(res, 200, listProjects.all());
    const match = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && match) {
      const project = findProject.get(match[1]);
      return json(res, project ? 200 : 404, project || { error: 'Project not found' });
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      if (!findProject.get(projectId)) return json(res, 404, { error: 'Project not found' });
      if (req.method === 'GET' && !taskId) return json(res, 200, listTasks.all(projectId).map(taskData));
      if (req.method === 'POST' && !taskId) {
        const input = await readBody(req);
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const result = createTask.run(projectId, title);
        return json(res, 201, taskData(findTask.get(projectId, Number(result.lastInsertRowid))));
      }
      if (req.method === 'PATCH' && taskId) {
        if (!findTask.get(projectId, taskId)) return json(res, 404, { error: 'Task not found' });
        const input = await readBody(req);
        if (typeof input?.completed !== 'boolean') return json(res, 400, { error: 'Completion must be a boolean' });
        updateTask.run(Number(input.completed), projectId, taskId);
        return json(res, 200, taskData(findTask.get(projectId, taskId)));
      }
    }
    if (req.method === 'POST' && path === '/api/projects') {
      const input = await readBody(req);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(res, 201, { id: Number(result.lastInsertRowid), name });
    }
    const asset = assets.get(path) || (/^\/projects\/\d+$/.test(path) ? assets.get('/') : undefined);
    if (req.method === 'GET' && asset) {
      res.writeHead(200, { 'Content-Type': asset[0], 'Cache-Control': 'no-cache' });
      return res.end(asset[1]);
    }
    json(res, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(res, error.status, { error: error.message });
    console.error(error);
    if (!res.headersSent) json(res, 500, { error: 'Server error' });
    else res.end();
  }
});
server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

const app = document.querySelector('#app');

function element(tag, text) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  return node;
}
function button(label, action) {
  const node = element('button', label);
  node.type = 'button';
  node.addEventListener('click', action);
  return node;
}
async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to load projects');
  return data;
}
function alert(message) {
  const node = element('p', message);
  node.setAttribute('role', 'alert');
  return node;
}
async function renderTasks(projectId) {
  const path = `/api/projects/${projectId}/tasks`;
  const form = element('form');
  const label = element('label', 'Task title');
  label.htmlFor = 'task-title';
  const input = element('input');
  input.id = 'task-title';
  input.type = 'text';
  const create = element('button', 'Create task');
  create.type = 'submit';
  create.disabled = true;
  form.append(label, input, create);
  const errorBox = element('div');
  const filterLabel = element('label', 'Task filter');
  filterLabel.htmlFor = 'task-filter';
  const filter = element('select');
  filter.id = 'task-filter';
  for (const value of ['All', 'Open', 'Completed']) {
    const option = element('option', value);
    option.value = value;
    filter.append(option);
  }
  const list = element('section');
  list.setAttribute('aria-label', 'Tasks');
  app.append(form, errorBox, filterLabel, filter, list);
  let tasks = [];
  function displayTasks() {
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed || filter.value === 'Completed' && !task.completed) continue;
      const row = element('div');
      row.className = 'task-row';
      row.dataset.testid = 'task-row';
      const checkbox = element('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        errorBox.replaceChildren();
        try {
          const saved = await request(`${path}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          task.completed = saved.completed;
          displayTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          errorBox.append(alert(error.message));
        } finally { checkbox.disabled = false; }
      });
      row.append(checkbox, element('span', task.title));
      list.append(row);
    }
  }
  filter.addEventListener('change', displayTasks);
  try {
    tasks = await request(path);
    displayTasks();
    create.disabled = false;
  } catch (error) { errorBox.append(alert(error.message)); }
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    errorBox.replaceChildren();
    const title = input.value.trim();
    if (!title) {
      errorBox.append(alert('Task title is required'));
      input.focus();
      return;
    }
    create.disabled = true;
    try {
      tasks.push(await request(path, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
      }));
      displayTasks();
      input.value = '';
      input.focus();
    } catch (error) { errorBox.append(alert(error.message)); }
    finally { create.disabled = false; }
  });
}
async function render() {
  app.replaceChildren();
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    app.append(button('Projects', () => { location.href = '/'; }));
    try {
      const project = await request(`/api/projects/${match[1]}`);
      app.append(element('h1', project.name));
      document.title = `${project.name} · Workboard`;
      await renderTasks(project.id);
    } catch (error) { app.append(alert(error.message)); }
    return;
  }
  document.title = 'Workboard';
  app.append(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  const create = element('button', 'Create project');
  create.type = 'submit';
  const errorBox = element('div');
  const list = element('section');
  list.setAttribute('aria-label', 'Projects');
  const empty = element('p', 'No projects yet. Create your first project above.');
  function addProject(project) {
    empty.remove();
    const row = element('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    row.append(element('span', project.name), button('Open project', () => {
      location.href = `/projects/${project.id}`;
    }));
    list.append(row);
  }
  form.append(label, input, create);
  app.append(form, errorBox, list);
  create.disabled = true;
  try {
    const projects = await request('/api/projects');
    if (!projects.length) list.append(empty);
    projects.forEach(addProject);
    create.disabled = false;
  } catch (error) { errorBox.replaceChildren(alert(error.message)); }
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    errorBox.replaceChildren();
    const name = input.value.trim();
    if (!name) {
      errorBox.append(alert('Project name is required'));
      input.focus();
      return;
    }
    create.disabled = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
      });
      addProject(project);
      input.value = '';
      input.focus();
    } catch (error) { errorBox.append(alert(error.message)); }
    finally { create.disabled = false; }
  });
}
render();

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import net from 'node:net';

test('projects and tasks validate, stay isolated and survive server restart', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const probe = net.createServer();
  probe.listen(0, '127.0.0.1');
  await once(probe, 'listening');
  const port = probe.address().port;
  await new Promise(resolve => probe.close(resolve));
  const base = `http://127.0.0.1:${port}`;
  let server;
  async function start() {
    server = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'projects.sqlite') },
      stdio: 'ignore',
    });
    for (let i = 0; i < 100; i++) {
      try {
        const response = await fetch(`${base}/health`);
        assert.equal(response.status, 200);
        assert.deepEqual(await response.json(), { status: 'ok' });
        return;
      } catch { await new Promise(resolve => setTimeout(resolve, 30)); }
    }
    throw new Error('Server did not become healthy');
  }
  async function stop() {
    if (server && server.exitCode === null) {
      const exited = once(server, 'exit');
      server.kill('SIGTERM');
      await exited;
    }
  }
  async function create(name) {
    return fetch(`${base}/api/projects`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });
  }
  try {
    await start();
    const invalid = await create('   ');
    assert.equal(invalid.status, 400);
    assert.equal((await invalid.json()).error, 'Project name is required');
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), []);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('Second project')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    const tasksPath = `/api/projects/${first.id}/tasks`;
    async function taskRequest(path, method, body) {
      return fetch(base + path, {
        method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
      });
    }
    for (const title of ['', '   ']) {
      const response = await taskRequest(tasksPath, 'POST', { title });
      assert.equal(response.status, 400);
      assert.equal((await response.json()).error, 'Task title is required');
    }
    assert.deepEqual(await (await fetch(base + tasksPath)).json(), []);
    const taskResponse = await taskRequest(tasksPath, 'POST', { title: '  First task  ' });
    assert.equal(taskResponse.status, 201);
    const task = await taskResponse.json();
    assert.equal(task.title, 'First task');
    assert.equal(task.completed, false);
    const nextTask = await (await taskRequest(tasksPath, 'POST', { title: 'Second task' })).json();
    assert.deepEqual(await (await fetch(base + tasksPath)).json(), [task, nextTask]);
    const otherPath = `/api/projects/${second.id}/tasks`;
    assert.deepEqual(await (await fetch(base + otherPath)).json(), []);
    const wrongOwner = await taskRequest(`${otherPath}/${task.id}`, 'PATCH', { completed: true });
    assert.equal(wrongOwner.status, 404);
    const checked = await taskRequest(`${tasksPath}/${task.id}`, 'PATCH', { completed: true });
    assert.equal(checked.status, 200);
    assert.equal((await checked.json()).completed, true);
    const invalidCompletion = await taskRequest(`${tasksPath}/${task.id}`, 'PATCH', { completed: 'false' });
    assert.equal(invalidCompletion.status, 400);
    await stop();
    await start();
    assert.deepEqual(await (await fetch(base + tasksPath)).json(), [{ ...task, completed: true }, nextTask]);
    assert.deepEqual(await (await fetch(base + otherPath)).json(), []);
    const unchecked = await taskRequest(`${tasksPath}/${task.id}`, 'PATCH', { completed: false });
    assert.equal(unchecked.status, 200);
    assert.equal((await unchecked.json()).completed, false);
    await stop();
    await start();
    assert.deepEqual(await (await fetch(base + tasksPath)).json(), [task, nextTask]);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    for (const path of ['/', `/projects/${first.id}`]) {
      const response = await fetch(base + path);
      assert.equal(response.status, 200);
      assert.match(await response.text(), /<title>Workboard<\/title>/);
    }
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

:root { font-family: system-ui, sans-serif; color: #172438; background: #f3f6fa; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #dbe2ec; border-radius: 12px; }
h1 { margin-top: 0; font-size: 2rem; overflow-wrap: anywhere; }
form { display: grid; grid-template-columns: 1fr auto; gap: 10px; margin-bottom: 24px; }
label { grid-column: 1 / -1; font-weight: 600; }
input, button, select { font: inherit; border-radius: 6px; padding: 10px 14px; }
input { min-width: 0; border: 1px solid #8996a7; }
button { cursor: pointer; color: white; background: #245bc0; border: 1px solid #245bc0; }
button:hover { background: #194697; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #e0a623; outline-offset: 3px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 16px 0; border-top: 1px solid #dbe2ec; }
.project-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row button { flex-shrink: 0; }
.task-row { display: flex; align-items: center; gap: 12px; padding: 16px 0; border-top: 1px solid #dbe2ec; }
.task-row span { overflow-wrap: anywhere; min-width: 0; }
.task-row input { flex-shrink: 0; width: 20px; height: 20px; }
#task-filter { margin: 0 0 20px 12px; border: 1px solid #8996a7; background: white; }
[role="alert"] { color: #a12222; }
main > button { margin-bottom: 24px; }
@media (max-width: 600px) { main { margin: 20px 12px; padding: 20px; } form { grid-template-columns: 1fr; } }

